values ((select id from public.teams limit 1), $il$i034$il$, $il$Reject in the top corner skips the reason dialog that Reject at the bottom shows$il$, $il$Lovable UI$il$, $il$Brad$il$, $il$nice$il$, $il$open$il$, $il$Oliver$il$, '2026-09-09T10:45:55.000Z'::timestamptz, 5, '{}'::text[], '{}'::text[], null, null, false, false, $il${}$il$::jsonb,
$il$Reject at the foot of the draft opens the Reject dialog with a reason picker. The Reject control in the top right corner does not, it just rejects. Point the top control at the same dialog. The bottom behaviour is the correct one.$il$,
$il$Worth saying why the reason matters beyond tidiness. Reject reasons are the only structured record of what is wrong with the drafting, so a silent reject is a lost training signal for the draft stack in i007. Anywhere a draft can be rejected, the reason should be captured.$il$);

insert into public.improvements (team_id, item_key, title, category, owner, priority, status, raised_by, created_at, build_wave, blocks, blocked_by, done_by, done_at, pinned, hidden, seen_by, detail, notes)
values ((select id from public.teams limit 1), $il$i035$il$, $il$External links on lead and company names should open in a new tab$il$, $il$Lovable UI$il$, $il$Brad$il$, $il$nice$il$, $il$open$il$, $il$Oliver$il$, '2026-09-09T11:10:08.000Z'::timestamptz, 5, '{}'::text[], array[$il$i032$il$]::text[], null, null, false, false, $il${}$il$::jsonb,
$il$The lead name and the company name on the outreach card should open in a new tab, target blank with rel noopener noreferrer. Only OUTWARD links: LinkedIn, Sales Nav, the partner site, a policy document. Links that navigate inside Lovable stay in the same tab. Low priority and open to debate.$il$,
$il$One distinction to hold, or this gets annoying fast. Only OUTWARD links open in a new tab: LinkedIn, Sales Nav, the partner website, a policy or IPID document. Links that move around INSIDE Lovable, such as a lead name that opens the lead record, should stay in the same tab, because a new tab per record turns into twenty tabs by lunchtime.

Worth Brad checking one thing first: if these are already real anchor tags then Cmd click, or middle click, already opens them in a new tab today and this is a default preference rather than a missing feature. If they are click handlers in script, Cmd click does nothing and that is the real defect, in which case make them proper anchors rather than adding a new tab call to the handler. Proper anchors also give us hover preview of the destination and copy link address, which the handler version silently loses.

Oliver logged this as low priority and open to debate.$il$);

